test("fixed seeded token corpus: no sample regresses from main 226dd628", (t) => {
  let index = 0, limits = 0;
  const failures: string[] = [];
  for (const row of randomRows()) {
    const baselinePass = (baselineBits[index >> 3] & (1 << (index % 8))) !== 0;
    const good = passes(row, redactSecrets(row.input).text);
    const expectedGood = (expectedBits[index >> 3] & (1 << (index % 8))) !== 0;
    if (good !== expectedGood && failures.length < 10) failures.push(`known limit changed: ${index} ${row.label}`);
    if (!good) { limits++; if (baselinePass && failures.length < 10) failures.push(`${index} ${row.label}`); }
    index++;
  }
  t.diagnostic(`seeded entries=${index}; known limits=${limits}; regressions=${failures.length}`);
  assert.equal(index, 226000);
  assert.deepEqual(failures, []);
});
