test("fixed performance corpus: adversarial scans stay below two seconds each", (t) => {
  for (const [label, input] of performanceRows) {
    const started = performance.now();
    redactSecrets(input, HOME_PREFIX);
    const ms = performance.now() - started;
    t.diagnostic(`${label}: ${input.length} chars, ${ms.toFixed(1)} ms`);
    assert.ok(ms < 2000, `${label}: ${ms.toFixed(1)} ms`);
  }
});
